    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if isinstance(document, dict):  # New JSON format
        if "subject" in document and "aliases" in document:
            return {
                "subject": document["subject"],
                "aliases": document["aliases"],
            }
        elif "subject" in document and "link" in document:
            return {
                "subject": document["subject"],
                "aliases": document["link"],
            }
        else:
            return {}
    else:
        # XRD (old) format
        root = XML_Node.from_xml(document)
        links = []
        for link_tag in root.find_all("Link"):
            links.append(
                {
                    "title": link_tag.find("Title").text,
                    "rel": link_tag.find("Rel").text,
                    "type": link_tag.find("Type").text,
                    "href": link_tag.find("Href").text,
                }
            )
        return {
            "subject": root.find("Subject").text,
            "aliases": links,
        }

