    for argname, argdict in self.parsed_yaml.get('args', {}).items():
        choices = argdict.get('choices')
        if choices is not None:
            choices_dict[argname] = choices

    # Check if the value of each choice argument is one of the available choices
    for argname, value in args.items():
        if argname in choices_dict:
            if value not in choices_dict[argname]:
                msg = "Invalid value for {0}: {1} (expected one of {2})"
                self.raise_program_error(msg.format(argname, value,
                                                      choices_dict[argname]))

def create_complex_argumet_type(self, subcommand, type_name, option_name, 
spec_option):
    """Build the complex argument type
        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
    if type_name == 'flags':
        return ComplexFlagType(subcommand, option_name, spec_option)
    elif type_name == 'options':
        return ComplexOptionType(subcommand, option_name, spec_option)
    elif type_name == 'args':
        return ComplexArgType(subcommand, option_name, spec_option)
    else:
        raise Exception(f'Unsupported complex argument type: {type_name}')

def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom. Controls arguments are used to control the IR behavior and will not be put into the spec yml file. Nested arguments are used by the Ansible playbooks and will be put into the spec yml file. Custom arguments are custom ansible variables to be used instead of the normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    level1_args = [
        'action',
        'module',
        'scenario',
        'subcommand',
        'verbosity',
    ]

    level2_args = [
        'disable',
        'from_yaml',
        'version',
    ]

    level3_args = [
        'arguments',
        'test',
    ]

    control_args = {}
    nested_args = {}
    custom_args = {}

    for k, v in args.items():
        if k in level1_args:
            control_args[k] = v
        elif k in level2_args:
            nested_args[k] = v
        else:
            custom_args[k] = v

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend `vars_dict` with `extra-vars`

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars:
        for var in extra_vars:
            if var not in vars_dict:
                vars_dict[var] = extra_vars[var]
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for option, value in values_dict.items():
        try:
            option_info = self._parser_options[parser_name][option]
            if option_info.type_:
                if option_info.type_ in [int, float]:
                    values_dict[option] = option_info.type_(value)
                elif option_info.type_ == bool:
                    values_dict[option] = value.lower() in ["true", "True", "1"]
        except KeyError:
            pass
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    with open(os.path.join(plugin_dir, "spec.json"), "r") as f:
        plugin_spec = json.load(f)

    flat_spec = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            flat_spec.update(get_plugin_spec_flatten_dict(value))
        else:
            flat_spec[key] = value

    return flat_spec

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    if os.getenv('config_path') is None:
        os.environ['config_path'] = self.config_path
